-- Notes on the provenance of single data files, checked by a person against the code and the data (kept by hand).
-- Each note states what was seen on the date checked, with its evidence (file:line in the repository, or the CAPRI file
-- compared); a note goes stale when its builder or readers change, so a change to them is the moment to check it again.
-- First filled 29 October 2026: the origin notes from the 18 entries of DATA_SOURCING_REGISTRY.json that name a live
-- file, the gaps from the known gaps and notes of INPUT_SCHEMA.json and INPUT_MANIFEST.json; what still holds was
-- kept, the rest dropped (their text stays in git history; the registry's log is in docs/KNOWN_ISSUES_REGISTRY_LOG.md).
-- A note may concern a JSON data file (not declared, so not in provenance).

CREATE TABLE provenance_notes (
    file VARCHAR NOT NULL,
    kind VARCHAR NOT NULL CHECK (kind IN ('origin', 'gap')),
    n INTEGER NOT NULL,
    note VARCHAR NOT NULL,
    evidence VARCHAR NOT NULL,
    checked DATE NOT NULL,
    PRIMARY KEY (file, kind, n)
);
COMMENT ON TABLE provenance_notes IS 'checked statements on a data file: its origin, content and readers (origin), or a limitation a user of the file should know (gap); with evidence';


-- rule: a file without a builder has a checked note on its origin
SELECT p.file FROM provenance p LEFT JOIN provenance_notes n USING (file) WHERE p.nature IN ('capri', 'external') AND p.builder IS NULL AND n.file IS NULL;

-- rule: a note concerns a declared data file or a JSON data file
SELECT DISTINCT file FROM provenance_notes WHERE file NOT IN (SELECT file FROM provenance) AND NOT ends_with(file, '.json');
