INSERT INTO provenance_notes VALUES
  ('capri_data/2017/environment/climate_zones.csv', 'origin', 1, 'Climate-zone shares (pct) by CAPRI region code (145 codes, 521 rows; zones Cool/Temperate and climate cells 10-19). 520 of the 521 rows equal CAPRI''s p_shareClimZone0 (dat/envind/climdat_gascoeff.gdx, loaded in gascoeff.gms:522) and AD_basedata p_Clima value for value. The extra row DK000000 zone 10 = 100 matches CAPRI''s completion rule (gascoeff.gms:545). No builder; it arrived with the repository''s first commit. Read only by tools/build/build_ad_option.py, which keeps the numeric cells; not by the model.', 'git log --follow: only c7d3dd5 ''0.2'' (2026-10-15); tools/build/build_ad_option.py:49, :97-100, :133-134; capri_mod/data/loaders.py:92 (folder map only, no loader); /home/claude/work/allgms/gams/envind/gascoeff.gms:119, :522, :544-545; comparison with /home/claude/work/hf_capri/dat/envind/climdat_gascoeff/p_shareClimZone0.parquet (520 matched, max |diff| 0) and hf_capri/dat/scen/ghgtech/AD_basedata/p_Clima.parquet (520 matched; p_Clima has LU000000 cool, the CSV has DK000000 10 instead); docs/AD_SPEC.md:305', DATE '2026-10-29'),
  ('capri_data/2017/market/producer_prices.csv', 'origin', 1, 'An EU-wide price per activity (32 rows, EUR/t), only the fallback under the regional prices. Each crop row is CAPRI''s production-weighted EU price from capreg_producer_prices.csv (CAPRI''s regional MPRI, national MPRI where no regional). SHGM and SHGF are herd-weighted. SETA 0 comes from sources/unsourced/producer_prices_no_builder.csv. The model reads it and overrides it per region with capreg_producer_prices.csv (loaders.load_regional_producer_prices, supply_module._region_prices).', 'tools/build/build_eu_producer_prices.py:1-15, :35-60; capri_mod/data/loaders.py:299-362 (regional, national fallback), :373-382; capri_mod/supply/supply_module.py:5478-5488; CSV: 32 rows (OVEG 509.1, TOBA 3003.4, OFRU 889.2)', DATE '2026-10-29'),
  ('capri_data/2017/market/world_prices.csv', 'origin', 1, 'World prices (EUR/t), 60 rows, every row from CAPRI''s FAO_agg p_dataMarket ''World'' PMRK BAS under the commodity''s CAPRI code. OLIV is derived (OLIO price x EU oil extraction) and FPRI is export-weighted from CAPRI''s 2017 market. DWHE and SUGB are kept only for the outer loop''s price signal. Provenance per row is in sources/world_price_provenance.csv (a JSON file until 30 October 2026). Read by the model (loaders.load_world_prices; model.py price signal) and by the market test as its reference.', 'tools/build/build_world_prices.py:1-25; capri_mod/data/loaders.py:432-441; capri_mod/model.py:526-567; capri_mod/tests/test_capri.py:119-128; CSV: 60 rows, EGGS 1073.04, OLIV 520.70, no SHGM row', DATE '2026-10-29'),
  ('capri_data/2017/policy/cap_payments.csv', 'origin', 1, 'One row per regional unit (221). BPS = CAPRI''s PRME per ha of UAAR (e.g. AT110000 533.12 = res_17 UAAR PRME), and ANC, AES, ORGANIC and COUPLED are 0 because CAPRI''s results carry no split by instrument. It feeds the DirectPaymentsEngine''s regional totals (policy report); crop premiums in the margin come from crop_premium.csv and livestock_premium_coef.csv, with no fallback to BPS.', 'tools/build/build_crop_economics_2017.py:32-34, :167-173; capri_mod/policy/policy_module.py:165, :212-220; capri_mod/supply/supply_module.py:2365-2378, :5068-5071, :5125-5128 (legacy shock path only); capri_mod/tests/test_capri.py:2629-2630; CSV: 221 x 5, ANC/AES/ORGANIC/COUPLED all 0', DATE '2026-10-29'),
  ('capri_data/2017/supply/animal_numbers.csv', 'origin', 1, 'Herds (1000 head) for the 221 regional units from CAPRI''s 2017 HERD item; COWS = DCOW + SCOW; PIGS = sows (CAPRI SOWS), PIGF = CAPRI''s PIGS census herd minus sows (Norway: CAPRI''s PIGF herd); SHGM and SHGF are CAPRI''s two sheep-and-goat herds. Read by the model (loaders.load_regional_animal_numbers, which renames to model codes) and by 15 builders.', 'tools/build/build_capri_base.py:105-108 (HERD_MAP), :206-215, :233; capri_mod/data/loaders.py:147-169, :567; tools/pipeline/builders.json; CSV: 221 x 12 (index unnamed), COWS == DCOW+SCOW in every row', DATE '2026-10-29'),
  ('capri_data/2017/supply/base_areas.csv', 'origin', 1, 'Crop areas (1000 ha) for the 221 regional units (6 in Norway), 34 crop columns, every cell CAPRI''s 2017 LEVL from the res_17<MS> dumps through build_capri_base.CROP_MAP (OFOD = OFAR+ROOF, SETA = SETA+FALL, WINE = TWIN, TEXT one column). Read by the model (loaders.load_regional_base_areas -> data[''areas'']) and by eleven builders. Nothing else in the registry entry survives; see the builder docstring.', 'tools/build/build_capri_base.py:43-45 (one writer, every cell from the dumps), :82-101 (CROP_MAP), :233; capri_mod/data/loaders.py:134-143, :561; tools/pipeline/builders.json (writer build_capri_base); CSV: 221 rows x 34 cols, no NaN, no COTT/OFIB columns; AT110000 row sum 190.33 = res_17AT ''AT110000''.''UAAR''.''LEVL'' 190.33', DATE '2026-10-29'),
  ('capri_data/2017/supply/land_availability.csv', 'origin', 1, 'Land by type (1000 ha) for the 221 regional units, derived from the rebuilt base_areas, not read from separate CAPRI land items. GRASSLAND = GRAS (CAPRI GRAS LEVL), FALLOW = SETA column (CAPRI SETA+FALL), PERMANENT = the seven permanent-crop columns, ARABLE = the rest. Read by the model (loaders.load_land_availability -> data[''land'']; supply_module land rows; DirectPaymentsEngine UAA).', 'tools/build/build_capri_base.py:224-230, :233; capri_mod/data/loaders.py:420-428, :732; capri_mod/supply/supply_module.py:592-601; capri_mod/policy/policy_module.py:219; CSV: 221 x 4, GRASSLAND == base_areas.GRAS, FALLOW == base_areas.SETA, row sums == base_areas row sums', DATE '2026-10-29'),
  ('capri_data/2017/supply/pmp_own_price_elasticities.csv', 'origin', 1, 'CAPRI''s raw PELA own-price elasticities per CAPRI region (228 codes) and crop (15, CAPRI codes incl. MAIZ and OFAR), 2375 pairs. Values are from 2005 where PELA has one, and an earlier year for the rest per the builder. Read by the model as the lower-precedence PMP_CAPRI source of capri_pmp.build_elasticity_table, dampened on load and aliased MAIZ->CORN, OFAR->OFOD.', 'tools/build/build_pmp_own_price_elasticities.py:1-14, :33-49; capri_mod/supply/capri_pmp.py:127, :135, :180-205; CSV: 2375 rows, 228 regions, max 110.998 (DEB20000 OATS)', DATE '2026-10-29'),
  ('capri_data/2017/supply/supply_elasticities_regional.csv', 'origin', 1, 'Own-price elasticities of 15 arable crops for 198 regional units. CAPRI''s PELA (dat/estnlp/results.gdx), 2005 own-price slice, bounded by CAPRI''s rule: values above 4.5 become min(8, sqrt(e) + 4.5 - sqrt(4.5)) (impose_upper_bound_on_elasticity.gms:25); no cell sits at 4.5, max 8.0, e.g. DEB20000 OATS raw 111.0 -> 8.0. Read by the model as the highest-precedence crop source in capri_pmp.build_elasticity_table (called in SupplyModule.__init__). With the default pmp_source capri2030, covered crops take CAPRI''s exported 2030 terms.', 'tools/build/build_supply_elasticities_regional.py:1-13, :32-38; tools/build/ingest_pela_gtap.py:21-22, :55, :128; capri_mod/supply/capri_pmp.py:52-57, :126, :146-235; capri_mod/supply/supply_module.py:5630-5640, :457; capri_mod/settings/defaults.toml:102; /home/claude/work/allgms/gams/supply/pmp_terms/impose_upper_bound_on_elasticity.gms:25; capri_data/shared/model_parameters.csv:9-10; CSV: 198 x 15, 1937 values, 217 > 4.5, 0 == 4.5', DATE '2026-10-29'),
  ('capri_data/2017/supply/variable_costs.csv', 'origin', 1, 'Costs per ha (crops) or per head (some animals) as CAPRI''s TOIN, LEVL-weighted over the crop''s CAPRI activities, for the 221 regional units, with the member-state fallback. The animal columns DCOW, BULL, PIGF and OANI come from TOIN and SHGM/SHGF from tools/lib/_sheep_goat. BCOW, HFRS, CALV, PIGS, LAYS and BROI are blank, because animal costs come from livestock_cost_coef.csv. TOIN is CAPRI''s total intermediate input, and CAPRI defines GVAP = TOOU - TOIN per activity. Read by the model (loaders.load_variable_costs[_regional], supply_module._region_costs).', 'tools/build/build_crop_economics_2017.py:18-27, :112-133, :160-161; /home/claude/work/allgms/gams/capreg/def_eaa.gms:87 (GVAP = TOOU - TOIN); capri_mod/data/loaders.py:386-416, :730-731; capri_mod/supply/supply_module.py:2319-2329, :5494-5501; CSV: 221 x 46, 1333 NaN (six animal columns fully blank, BULL 1, OANI 6), 0 cells with OVEG == TOMA', DATE '2026-10-29'),
  ('capri_data/2017/supply/yields.csv', 'origin', 1, 'Crop yields in t/ha (CAPRI''s YILD / 1000) for the 221 regional units, LEVL-weighted over the crop''s CAPRI activities (build_capri_base.CROP_MAP); a crop the region does not grow takes its member state''s values, and 0 where CAPRI has it nowhere in the member state. Grass is kg fresh matter per ha from CAPRI''s GRAS output item, because CAPRI''s GRAS YILD item is revenue. The 12 animal columns come from build_animal_yields.py: YILD per model head, with dairy from DCOL/DCOH, whose YILD equals COMI (DE: 5752.7 and 9590.1). CAPRI''s aggregate DCOW YILD (2535.0 in DE) is not a milk yield.', 'tools/build/build_crop_economics_2017.py:14-27 (method, one writer), :82-99 (values), :138-165 (national fallback, 0 when absent), :177-192 (grass); tools/build/build_animal_yields.py:1-8, :32; /home/claude/work/capreg/res_17DE.txt (DE000000 SWHE YILD 7612.58, BARL 6648.16, DCOW YILD 2535.04, DCOL/DCOH YILD = COMI); capri_mod/data/loaders.py:47; capri_mod/supply/supply_module.py:4966, :5777; CSV: 221 x 46, no NaN, DE regions'' SWHE mean 7.36 t/ha', DATE '2026-10-29'),
  ('capri_data/shared/trade_flows_2017.csv', 'origin', 1, 'CAPRI''s 2017 bilateral ImportQ (capmod res_0_1717 cap_after_2014_cal_from_data), mapped to 26 model trade regions (incl. NOR and ROW), with CAPRI''s overlapping aggregates excluded. 601 pairs x 39 commodities, 32 with any flow; it includes intra-EU trade (EU27 -> EU27). The market does not read it (it uses 2017/market/bilateral_flows_*.csv). It is loaded only by the data check (validate_data.py:159, a loadability check, as trade_flows.csv via loaders._SHARED_FILES) and read by tools/check/validate_world_prices.py.', 'tools/build/recalibrate_trade_2017.py:66-96, :115-170; capri_mod/data/loaders.py:95, :112-113, :547-550; capri_mod/data/validate_data.py:157-162; tools/check/validate_world_prices.py:81; CSV: 601 x 41, EU27/EU27 row sum 637010', DATE '2026-10-29'),
  ('capri_data/sources/arm/capri_supply_elas_market_1717.csv', 'origin', 1, 'Every record of CAPRI''s p_elasSupp(region, prod, wrt, ''CAL'') from elas1717defaulta (73528 rows, 80 regions of which 34 are CAPRI national codes, 45 products, 2635 own-price records). Market level: country and trade-region codes, market products. Read by the model in capri_pmp.build_elasticity_table for the livestock elasticities (each animal takes its product''s member-state value) and by build_supply_elas_nonEU.py. Its EU medians go to 2017/market/supply_elas_eu.csv, read by capri_mod/market/supply.py: MILK 0.556, BEEF 0.719, PORK 0.690, EGGS 0.761, POUM 0.750, SGMT 0.816.', 'tools/build/build_capri_supply_elas_market.py:1-16, :40-66; capri_mod/supply/capri_pmp.py:136-138, :250-300; tools/build/build_supply_elas_nonEU.py:6, :35; capri_mod/market/supply.py:113-118; capri_data/2017/market/supply_elas_eu.csv; CSV: 73528 rows, 80 regions, 45 prods, 2635 diagonal', DATE '2026-10-29'),
  ('capri_data/sources/capreg/pmp_quad_techn.csv', 'origin', 1, 'CAPRI''s 2017 p_pmpQuadTechn own-activity diagonal (quadTechn_*.txt). The regex accepts both T1.T1 (crops) and T.T (livestock) tags; MAIZ is renamed CORN. 10889 rows, 221 regional units, 56 activities, 19 of them animal activities incl. OANI. Not read by the model: inputs of build_cattle_intensity, build_dairy_intensity and build_grass_intensity, tools/check/pmp_recipe_check.py and one test. The default PMP uses CAPRI''s exported 2030 terms (sources/baseline_pmp/pmp_quad_techn_2030.csv).', 'tools/build/ingest_pmp_terms.py:33-34, :52-80; tools/build/build_cattle_intensity.py:40; tools/build/build_dairy_intensity.py:37; tools/build/build_grass_intensity.py:35; tools/check/pmp_recipe_check.py:77; capri_mod/tests/test_capri.py:3705; capri_mod/settings/defaults.toml:102; CSV: 10889 x 3, 221 regions, 56 activities', DATE '2026-10-29'),
  ('capri_data/sources/fao_2021/trade_flows_2021.csv', 'origin', 1, 'FAOSTAT 2021 bilateral trade (per sources/fao_2021/README.md), 29 x 29 trade regions (841 pairs, a full grid), 32 commodity columns, 13 with any flow. The EU27 -> EU27 diagonal is zero, so no intra-EU trade. No builder; it arrived with the first commit. Not read by the model. tools/build/recalibrate_trade_2017.py reads it as the comparison for its extra-EU share report, and also takes its column list as the commodity set of shared/trade_flows_2017.csv.', 'capri_data/sources/fao_2021/README.md:1-16; git log --follow: only c7d3dd5 ''0.2''; tools/build/recalibrate_trade_2017.py:124-126, :140-146; tools/pipeline/builders.json (input of recalibrate_trade_2017); CSV: 841 x 34, diagonal all 0', DATE '2026-10-29'),
  ('capri_data/sources/capri_dat/sugar/p_SQuotas.csv', 'origin', 1, 'CAPRI''s p_SQuotas(MSALL, QUOTAS, year), sugar quotas in 1000 t white sugar, of input_load_sugar_quotas.gdx (written by CAPRI''s sugar/load_quotas.gms from dat/sugar/*.gms). No builder: converted from the parquet mirror of CAPRI''s dat folder on 29 October 2026 with the columns renamed (README in the folder). Read by tools/build/build_captrd_dat.py for CAPTRD-MOD''s policy data.', 'capri_data/sources/capri_dat/sugar/README.md; comparison with /home/claude/work/hf_capri/dat/sugar/input_load_sugar_quotas/p_SQuotas.parquet on 30 October 2026: 582 of 582 rows, keys and values equal; tools/build/build_captrd_dat.py docstring', DATE '2026-10-30'),
  ('capri_data/sources/capri_dat/sugar/p_PPSQRenounce.csv', 'origin', 1, 'CAPRI''s p_PPSQRenounce(MSALL, year), renounced sugar quota, of input_load_sugar_quotas.gdx (written by CAPRI''s sugar/load_quotas.gms from dat/sugar/*.gms). No builder: converted from the parquet mirror of CAPRI''s dat folder on 29 October 2026 with the columns renamed (README in the folder). Read by tools/build/build_captrd_dat.py for CAPTRD-MOD''s policy data.', 'capri_data/sources/capri_dat/sugar/README.md; comparison with /home/claude/work/hf_capri/dat/sugar/input_load_sugar_quotas/p_PPSQRenounce.parquet on 30 October 2026: 35 of 35 rows, keys and values equal; tools/build/build_captrd_dat.py docstring', DATE '2026-10-30'),
  ('capri_data/sources/capri_dat/sugar/p_PPSQCBuyBack.csv', 'origin', 1, 'CAPRI''s p_PPSQCBuyBack(MSALL, year), sugar quota buy-back, of input_load_sugar_quotas.gdx (written by CAPRI''s sugar/load_quotas.gms from dat/sugar/*.gms). No builder: converted from the parquet mirror of CAPRI''s dat folder on 29 October 2026 with the columns renamed (README in the folder). Read by tools/build/build_captrd_dat.py for CAPTRD-MOD''s policy data.', 'capri_data/sources/capri_dat/sugar/README.md; comparison with /home/claude/work/hf_capri/dat/sugar/input_load_sugar_quotas/p_PPSQCBuyBack.parquet on 30 October 2026: 13 of 13 rows, keys and values equal; tools/build/build_captrd_dat.py docstring', DATE '2026-10-30');
INSERT INTO provenance_notes VALUES
  ('capri_data/2017/abatement/fert_side_effects.csv', 'gap', 1, 'Norway''s six regions have no own entry in CAPRI''s literature review and take the median over Norway''s CAPRI regions. The NOx effect of nitrification inhibitors (NOXSYN) is not carried.', 'tools/build/build_fert_side_effects.py:12, :30-33; capri_region ''NO median'' rows in fert_side_effects.csv; item list has no NOXSYN', DATE '2026-10-29'),
  ('capri_data/2017/environment/manure_pool_costs.json', 'gap', 1, 'The haul cost is fixed at CAPRI''s 0.18 EUR/t/km base value. CAPRI inflates it to the simulation year by p_infl (1.019 per year), so the model''s manure trade costs between pools are lower than CAPRI''s at 2030.', 'tools/build/build_manure_pool_costs.py:4-9; allgms/gams/manuremarket/define_manure_market_structure.gms:281-282; allgms/gams/captrd.gms:327', DATE '2026-10-29'),
  ('capri_data/2017/environment/p_balance_crop_coefs_2030.csv', 'gap', 1, 'The coefficients exist only for crops with a CAPRI 2030 level in the region. 258 region-crop cells with 2017 area (71 kha in total) have no regional row: 66 take the member state''s coefficient and the rest count zero P2O5 removal and residues.', 'capri_mod/environmental/p_balance.py:55-63; p_balance_crop_coefs_2030.csv vs base_areas.csv (computed today)', DATE '2026-10-29'),
  ('capri_data/2017/feed/feed_ration_2017.json', 'gap', 1, 'In 986 of 2,407 region-animal records, the base ration''s dry matter falls outside the file''s DMIN-DMAX range (worst: HR000000 broilers 2.4x DMAX). The ration model widens the DM bounds, and lowers the energy and protein requirements, to fit the base ration (CAPRI''s p_trimFeed). So the file''s requirements are not what binds at calibration.', 'capri_mod/feed/ration.py:14-15, :159-163; dry matter = sum(ration x DRMA) vs req DMIN/DMAX in feed_ration_2017.json (computed today)', DATE '2026-10-29'),
  ('capri_data/2017/feed/fodder_balance_2017.json', 'gap', 1, 'Usable fodder per ha is CAPRI''s base fodder use divided by base area, and in some regions it is implausible. For fodder maize: ES620000 246, ES520000 161 and IT920000 119 t/ha, against a median of 30.5, and DE910000 at 0.01 t/ha. The supply model uses it in its fodder balance.', 'tools/build/build_fodder_balance.py:4-6, :52; capri_mod/supply/supply_module.py:4397, :4640; values in fodder_balance_2017.json (computed today); docs/FODDER_BALANCE.md:57-60 (older list of outlier regions)', DATE '2026-10-29'),
  ('capri_data/2017/market/supply_elas_eu.csv', 'gap', 1, 'There is one value per market commodity (the median of CAPRI''s p_elasSupp over the 27 member states), and the market module applies it identically to every EU row. Member-state differences in CAPRI''s market supply elasticities are not carried there. EU supply itself comes from the supply models.', 'capri_mod/market/supply.py:112-120, :29-46 (EU rows take el)', DATE '2026-10-29'),
  ('capri_data/2017/policy/organic_yield_gap.csv', 'gap', 1, 'Organic yield gaps come at the resolution of five macro-regions by nine product groups: every member state in a macro-region gets the same gap. A missing cell (e.g. maize in NE; grass, maize and oilseeds in UK_IR) takes the Central-European value, as CAPRI does. Activities outside the groups get no gap.', 'capri_mod/supply/supply_module.py:2446-2471, :2773-2785; allgms/gams/pol_input/greendeal/organic_area.gms:162-163, :173-180', DATE '2026-10-29'),
  ('capri_data/2017/supply/capri_own_price_elasticities.csv', 'gap', 1, 'The model does read it: build_elasticity_table uses it as the member-state (CAPRI_COUNTRY) source for crops that neither PELA file covers. Under the default PMP terms it does not drive the crop response, because crops with a CAPRI term take that term and crops without one are held at their level.', 'capri_mod/supply/capri_pmp.py:128, :226-250; capri_mod/supply/supply_module.py:509-524, :5713-5729', DATE '2026-10-29'),
  ('capri_data/2017/supply/cover_crops.csv', 'gap', 1, 'biofix_t_n_ha is blank for 11 regions (ES70, IT12, MT, PT20, PT30 and Norway''s six), and the model takes 0 N fixation from catch crops there. Only ES700000 has a non-negligible catch-crop share (9% of UAA).', 'capri_mod/supply/supply_module.py:1246-1247, :2691-2693; cover_crops.csv rows (checked today)', DATE '2026-10-29'),
  ('capri_data/2017/supply/livestock_revenue_coef.csv', 'gap', 1, 'SHGM (milk sheep and goats) is blank in 28 regions with a herd (DK, FI, IE, NL, SE), because CAPRI books no market revenue (MREV) there. The supply model reads the blank as 0 and values the activity by total output (TOOU).', 'capri_mod/supply/supply_module.py:2339-2350; livestock_revenue_coef.csv vs animal_numbers.csv (computed today)', DATE '2026-10-29'),
  ('capri_data/2017/supply/mineral_n_price.csv', 'gap', 1, 'No effect on a standard run. Its only effective reader is the fertiliser allocation (use_fert_allocation), which is off by default and switched off by the outer loop. The manure-pool path fetches the price but does not use it.', 'capri_mod/supply/supply_module.py:3461-3467, :3484-3508, :3618-3619, :3684 (pf unused after); capri_mod/model.py:597', DATE '2026-10-29'),
  ('capri_data/2017/supply/nutrient_coefs_regional.csv', 'gap', 1, 'Column N is CAPRI''s NITF, which equals NRET, the crop''s N requirement. It is not the mineral N applied (NMIN, in nutrients_regional.csv). A crop the region does not grow takes its member state''s values.', 'tools/build/build_nutrient_coefs_regional.py:14-17; /home/claude/work/capreg/res_17DE.txt:103665,103674,103676 (DE110000 SWHE NITF = NRET = 147.54, NMIN = 77.33)', DATE '2026-10-29'),
  ('capri_data/2017/supply/nutrients_regional.csv', 'gap', 1, 'This is CAPRI''s mineral N applied (NMIN, kg/ha). A blank cell means zero mineral N in the environmental accounts; there is no fallback table. For OFOD the value is OFAR''s NMIN only (ROOF, under 1% of that area, is not included).', 'capri_mod/environmental/environmental_module.py:517-527; capri_mod/data/loaders.py:727-728; tools/build/build_capri_base.py:155-171, :221, :99', DATE '2026-10-29'),
  ('capri_data/2017/supply/pmp_capri_2030.csv', 'gap', 1, 'CAPRI''s two technologies per crop (T1 high-yield, T2 low-yield) are collapsed into one model activity with the curvature of the optimal split, so the area response follows CAPRI''s terms but the change in average yield that CAPRI gets from shifting between T1 and T2 is not represented.', 'tools/build/build_pmp_capri_2030.py:10-17; allgms/gams/capmod.gms:246-249 (SET A: T, T1, T2); docs/PMP_CAPRI_2030.md:149-150', DATE '2026-10-29'),
  ('capri_data/2017/supply/pmp_capri_2030.csv', 'gap', 2, 'These terms are used only when the market year is 2030; at the 2017 market year the default pmp_source ''capri2030'' takes the recipe terms (pmp_recipe_2017.csv) instead.', 'capri_mod/supply/supply_module.py:5675-5693; capri_mod/settings/defaults.toml:99-102', DATE '2026-10-29'),
  ('capri_data/2017/supply/pmp_capri_2030.csv', 'gap', 3, 'A crop with a base area but no positive own term in the region is held at its level, not calibrated. In the file, 258 region-crop cells with 2017 area (71 kha out of 166,690 kha) have no diagonal term, mostly OOIL, TOBA, TABO, OIND, TEXT and PULS.', 'capri_mod/supply/supply_module.py:5713-5729 (_uncalibrated), :509-524; count from pmp_capri_2030.csv diagonals vs 2017/supply/base_areas.csv (computed today)', DATE '2026-10-29'),
  ('capri_data/2017/supply/pmp_capri_2030_animals.csv', 'gap', 1, 'Each model animal sums several CAPRI activities. By default only the intensity pairs DCOL/DCOH, BULL/BULH and HEIL/HEIH get a combined curvature for the pair. The other members (replacement heifers HEIR, the four calf activities and so on) enter in fixed proportions, so CAPRI''s separate response of each member is not carried.', 'tools/build/build_animal_pmp_capri_2030.py:8-17, :51-62 (MEMBERS), :102', DATE '2026-10-29'),
  ('capri_data/2017/supply/pmp_capri_2030_animals_members.csv', 'gap', 1, 'Read only when RegionalSupplyModel.use_cattle_member_splits is on. It is off by default (a departure from CAPRI: the per-sex young-animal markets did not converge, K65), so a default run does not use this file. The same applies to pmp_recipe_2017_animals_members.csv and pmp_recipe_2030_animals_members.csv.', 'capri_mod/data/loaders.py:505-511; capri_mod/settings/defaults.toml:113-115', DATE '2026-10-29'),
  ('capri_data/2017/supply/pmp_recipe_2017.csv', 'gap', 1, 'Not only an optional alternative. With the default pmp_source ''capri2030'', any run at the 2017 market year uses these terms, because CAPRI''s exported terms exist only for 2030.', 'capri_mod/supply/supply_module.py:5684-5693; capri_mod/settings/defaults.toml:99-102', DATE '2026-10-29'),
  ('capri_data/2017/supply/pmp_recipe_2030.csv', 'gap', 1, 'The recipe''s own diagonal terms differ most from CAPRI''s exported 2030 terms for grassland (10th-90th percentile ratio 0.61-1.28) and set-aside (SETA, 0.69 to 20.6). Most other crops are within a few percent at the median. These terms are used only with pmp_source = ''recipe''.', 'ratio g(pmp_recipe_2030.csv)/g(pmp_capri_2030.csv) on matching diagonals (computed today); docs/PMP_CAPRI_2030.md:140-145; capri_mod/supply/supply_module.py:5689-5691', DATE '2026-10-29'),
  ('capri_data/2017/supply/winter_cover_share.csv', 'gap', 1, 'The as-given shares (share0) used by the Farm-to-Fork minimum catch-crop rule are non-zero in only 59 of 3,738 region-crop rows (Austria and a few German regions), so elsewhere that rule counts no existing winter cover. The column share is filled NUTS2 <- member state <- EU, as in CAPRI.', 'tools/build/build_cover_crops.py:11-17, :26; winter_cover_share.csv (share0 > 0 in 59 rows, computed today)', DATE '2026-10-29'),
  ('capri_data/2017/supply/young_animals_2017.json', 'gap', 1, 'This is the default young-animal table. It pools male and female calves and male and female young cattle into one balance each, where CAPRI clears them per sex. The pooled value per head is the unweighted mean of the two sexes'' national unit values (e.g. Spain young cattle 1019.7 = (1075.0 + 964.4)/2).', 'tools/build/build_young_animals.py:40-46, :58-61, :151; capri_mod/supply/supply_module.py:145-157; capri_mod/settings/defaults.toml:113-115; res_17ES.txt UVAG YBUL/YHEI', DATE '2026-10-29'),
  ('capri_data/2017/supply/young_animals_by_sex_2017.json', 'gap', 1, 'Read only when the cattle member splits are on, which is off by default (K65). A default run uses the pooled young_animals_2017.json instead.', 'capri_mod/supply/supply_module.py:145-157; capri_mod/settings/defaults.toml:113-115', DATE '2026-10-29');
